 v_os_cliente uuid; v_os_order uuid; v_resale boolean:=false;
BEGIN
 IF v_tipo='b2b' AND v_order IS NOT NULL AND v_os IS NOT NULL AND platform_private.b2b_internal_commercial_actor() IS TRUE THEN
