CREATE OR REPLACE FUNCTION public.trg_entrega_sync_partner_order_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_order_id uuid;
  v_total int; v_delivered int; v_order public.partner_orders; v_terminal public.partner_orders;
BEGIN
  SELECT os.partner_order_id INTO v_partner_order_id
    FROM public.ordens_servico os WHERE os.id = COALESCE(NEW.ordem_servico_id, OLD.ordem_servico_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;
  IF EXISTS(SELECT 1 FROM public.ordens_servico os WHERE os.id=NEW.ordem_servico_id
    AND os.origem='b2b' AND os.partner_order_id=v_partner_order_id)
   AND EXISTS(SELECT 1 FROM platform_private.b2b_resale_logistics_gate_v1 WHERE singleton AND enabled IS TRUE) THEN
   SELECT * INTO v_order FROM public.partner_orders WHERE id=v_partner_order_id FOR UPDATE;
   -- A entrega parcial já foi validada pelo permit; não tentar terminal cedo.
   IF v_order.status::text='entregue' THEN RETURN NEW; END IF;
   v_terminal:=jsonb_populate_record(v_order,jsonb_build_object('status','entregue'));
   IF platform_private.b2b_resale_delivery_status_transition_valid_v1(v_order,v_terminal) IS NOT TRUE THEN RETURN NEW; END IF;
   -- O gatilho canônico do pedido registra o evento terminal uma vez.
   -- Revenda não escreve planejamento de fabricação nem duplica timeline.
   UPDATE public.partner_orders SET status='entregue',updated_at=now()
    WHERE id=v_partner_order_id AND status='aprovado';
   RETURN NEW;
  END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE e.status = 'entregue')
    INTO v_total, v_delivered
    FROM public.entregas e
    JOIN public.ordens_servico os ON os.id = e.ordem_servico_id
   WHERE os.partner_order_id = v_partner_order_id AND e.status <> 'cancelada';

  IF v_total > 0 AND v_delivered = v_total THEN
    UPDATE public.partner_orders SET status = 'entregue', updated_at = now()
      WHERE id = v_partner_order_id AND status <> 'entregue';
    UPDATE public.production_planning SET status = 'entregue', updated_at = now()
      WHERE partner_order_id = v_partner_order_id;
    INSERT INTO public.production_timeline_events (partner_order_id, event_type, meta)
    VALUES (v_partner_order_id, 'entrega_realizada', jsonb_build_object('total', v_total));
  END IF;
  RETURN NEW;
END $function$

